//! The chunks a spawning pass walks, and the order it walks them in:
//! `ChunkMap.collectSpawningChunks` over `DistanceManager.naturalSpawnChunkCounter`
//! and then `ServerChunkCache.tickChunks`'s `Util.shuffle`, which spends one
//! draw of the level's random per chunk in that order.
//!
//! The expected lists were recorded from the real 26.3 classes, not from
//! Horizon: a `DistanceManager` subclass drove `naturalSpawnChunkCounter` with
//! the same `addPlayer` / `removePlayer` / `runAllUpdates` calls `ChunkMap`
//! makes, read the chunks back through `Long2ByteOpenHashMap.keySet()`,
//! filtered them with `playerIsCloseEnoughForSpawning`, and ran `Util.shuffle`
//! over them with a `LegacyRandomSource` (then took its next `nextInt`). So
//! neither the map's order nor the shuffle comes from the code under test.
use super::LevelPlayer;
use super::SpawnScratch;
use super::spawn_chunk_order::shuffle_spawning_chunks;
use horizon_core::geometry::{Aabb, Vec3};
use horizon_core::random::{LegacyRandom, RandomSource};

/// One recorded run: the players in the level after each tick (their id and
/// chunk, in the level's order), the chunks the next pass walks, and what
/// `Util.shuffle` makes of them with the level's random.
struct Case {
    name: &'static str,
    steps: &'static str,
    order: &'static str,
    shuffled: &'static str,
    next: i32,
    seed: i64,
}

fn chunks(list: &str) -> Vec<(i32, i32)> {
    list.split_whitespace()
        .map(|c| {
            let (x, z) = c.split_once(':').expect("x:z");
            (x.parse().expect("x"), z.parse().expect("z"))
        })
        .collect()
}

/// A player standing at its chunk's centre, which is where the recording
/// stood them.
fn player(uuid: u128, x: i32, z: i32) -> LevelPlayer {
    let position = Vec3::new(f64::from(x * 16 + 8), 64.0, f64::from(z * 16 + 8));
    LevelPlayer {
        uuid,
        position,
        bounds: Aabb::new(position, position),
        alive: true,
        creative: false,
        spectator: false,
    }
}

fn run(case: &Case) {
    let mut scratch = SpawnScratch::default();
    for step in case.steps.split('|').map(str::trim) {
        let players: Vec<LevelPlayer> = step
            .split_whitespace()
            .map(|p| {
                let mut fields = p.split(':').map(|n| n.parse::<i32>().expect("number"));
                let id = fields.next().expect("id");
                let x = fields.next().expect("x");
                let z = fields.next().expect("z");
                player(id as u128, x, z)
            })
            .collect();
        scratch.collect(&players, |_| true);
    }
    let mut walked = scratch.candidates.clone();
    assert_eq!(
        walked,
        chunks(case.order),
        "{}: the chunks a pass walks",
        case.name
    );
    let mut random = LegacyRandom::new(case.seed);
    shuffle_spawning_chunks(&mut walked, &mut random);
    assert_eq!(
        walked,
        chunks(case.shuffled),
        "{}: the order they are walked in",
        case.name
    );
    assert_eq!(
        random.next_int(),
        case.next,
        "{}: the level random after the shuffle",
        case.name
    );
}

